/** Registry arguments shared by runtime factories.
 * @since 1.0.0
 */
import * as Layer from "effect/Layer";
/** The registry layer the arguments name, or an empty layer when none was passed.
 * The empty branch can only be selected when all three registry types are never.
 * @since 1.0.0
 * @category layers
 */
export const registryLayer = (args) => (args[0] ?? Layer.empty);

/** Runtime configuration shared by injected and native hosts.
 * @since 1.0.0
 */
import { Action } from "@smthrs/flow";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";
/**
 * Stable failure raised synchronously for invalid runtime construction input.
 *
 * @since 1.0.0
 * @category errors
 */
export class RuntimeConfigurationError extends Schema.TaggedError()("@smthrs/flows/RuntimeConfigurationError", {
    code: Schema.Literal("invalid_runtime_configuration"),
    field: Schema.String,
    message: Schema.String
}) {
}
const invalidConfiguration = (field, message) => new RuntimeConfigurationError({ code: "invalid_runtime_configuration", field, message });
/**
 * Decodes one named option and reports the option that was wrong.
 *
 * A single struct decode would answer "options" for every refusal, and the
 * whole point of {@link RuntimeConfigurationError.field} is that an embedder
 * can tell an empty `filename` from an empty `owner.hostId` without reading
 * prose. Decoding field by field makes the name come from the call site rather
 * than from walking a schema issue tree. A host package decodes the options it
 * adds, such as a database filename, through this so its refusals carry the
 * same error and the host's own `label`.
 *
 * @since 1.0.0
 * @category validation
 */
export const decodeField = (field, schema, value, expectation, label = "Runtime") => {
    try {
        return Schema.decodeUnknownSync(schema)(value);
    }
    catch {
        throw invalidConfiguration(field, `${label} ${field} ${expectation}`);
    }
};
const nonEmpty = "must be a non-empty string";
/**
 * The sweep a runtime accepts: absent, `"process"`, or one host-driven
 * execution named by a non-empty id.
 */
const Sweep = Schema.UndefinedOr(Schema.Union([
    Schema.Literal("process"),
    Schema.Struct({ host: Schema.NonEmptyString, flow: Schema.optionalKey(Schema.NonEmptyString) })
]));
/**
 * Captures the injected runtime's options as one immutable record.
 *
 * Throws `RuntimeConfigurationError` naming the first option that is wrong,
 * with `label` leading its message. `layer` calls it; a host package that
 * composes the engine itself calls it before reading the options.
 *
 * @since 1.0.0
 * @category validation
 */
export const validate = (options, label = "Runtime") => {
    // A JavaScript caller can omit `owner` entirely, so the field is read off a
    // possibly-absent record rather than dereferenced.
    const owner = options.owner;
    const hostId = decodeField("owner.hostId", Schema.NonEmptyString, owner?.hostId, nonEmpty, label);
    const isAlive = options.isAlive;
    if (typeof isAlive !== "function") {
        throw invalidConfiguration("isAlive", `${label} isAlive must be a function`);
    }
    const canExecute = options.canExecute;
    if (canExecute !== undefined && typeof canExecute !== "function") {
        throw invalidConfiguration("canExecute", `${label} canExecute must be a function when supplied`);
    }
    const canActivate = options.canActivate;
    if (canActivate !== undefined && typeof canActivate !== "function") {
        throw invalidConfiguration("canActivate", `${label} canActivate must be a function when supplied`);
    }
    const requestResume = options.requestResume;
    if (requestResume !== undefined && typeof requestResume !== "function") {
        throw invalidConfiguration("requestResume", `${label} requestResume must be a function when supplied`);
    }
    // Decoded rather than trusted: this value is cache key material, and a
    // malformed one would silently key every sealed result of this host.
    const cacheEnvironment = options.cacheEnvironment === undefined ? undefined : decodeField("cacheEnvironment", Action.CacheEnvironment, options.cacheEnvironment, "must name every runtime layer and capability group", label);
    // A ref a reader cannot resolve is not a revision: a declared one is refused
    // where it is written rather than recorded onto every page of every run. A
    // reader is checked for its shape only; its answers are checked by the store
    // that asks for them, because none of them exists yet.
    const sourceRevision = options.sourceRevision === undefined || typeof options.sourceRevision === "function"
        ? options.sourceRevision
        : decodeField("sourceRevision", Schema.NonEmptyString, options.sourceRevision, nonEmpty, label);
    const privilegedJj = options.privilegedJj;
    if (privilegedJj !== undefined && !Layer.isLayer(privilegedJj)) {
        throw invalidConfiguration("privilegedJj", `${label} privilegedJj must be a Layer when supplied`);
    }
    const sweep = decodeField("sweep", Sweep, options.sweep, "must be \"process\" or { host: <execution id> }", label);
    const placement = options.placement === undefined
        ? undefined
        : decodeField("placement", Schema.NonEmptyString, options.placement, nonEmpty, label);
    const resumeConcurrency = options.resumeConcurrency === undefined
        ? undefined
        : decodeField("resumeConcurrency", Schema.Int.check(Schema.isGreaterThanOrEqualTo(1)), options.resumeConcurrency, "must be a positive integer", label);
    return Object.freeze({
        owner: Object.freeze({ hostId }),
        isAlive,
        canExecute,
        canActivate,
        requestResume,
        cacheEnvironment,
        sourceRevision,
        privilegedJj,
        sweep,
        resumeConcurrency,
        placement
    });
};
